"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-01-01:0":{"b": ["نیپلز کے ڈیوک سرجیئس چہارم نے اورسا نارمن رینولف کو دے دیا؛ جنوبی اٹلی میں پہلی نارمن کاؤنٹی وجود میں آئی", "b9d840ee"], "d": ["ڈیوک سرجیئس چہارم کاپوا کے شہزادے پانڈولف کے خلاف حمایت کے عوض نارمن رینولف کو اورسا دیتا ہے؛ جنوبی اٹلی میں پہلی نارمن کاؤنٹی وجود میں آتی ہے۔", "c5cc04b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-01-01:1":{"b": ["یاروسلاو دانا نے جھیل پیپوس اور بالٹک کے درمیان کا علاقہ فتح کر کے یوریف (تارتو) کی بنیاد رکھی", "40165af3"], "d": ["1030 میں یاروسلاو نے جھیل پیپوس اور بالٹک کے درمیان کے علاقے فتح کیے اور وہاں اپنے عیسائی نام یوری (گیورگی) سے ماخوذ یوریف شہر بسایا؛ شہر آج کے اسٹونیا کا تارتو ہے۔", "9dcb000d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-07-29:0":{"b": ["جنگِ اشٹیکلستاد: بادشاہ اولاو دوم ہرالدسن ٹرونڈلاگ میں مارا گیا", "b774bc0b"], "d": ["29 جولائی (غالباً 1030) کو ٹرونڈلاگ کے اشٹیکلستاد (آج کا ویردال) میں اولاو، جلاوطنی سے لوٹ کر ناروے واپس لینا چاہتے ہوئے علاقے کے عمائدین اور کسانوں سے ٹکرایا اور مارا گیا۔ اولاو بعد میں ناروے کا قومی ولی بنا؛ ڈنمارک کی حکمرانی کچھ سال جاری رہی۔", "6e621a73"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1032-01-01:0":{"b": ["اورسیولو خاندان جلاوطن کر دیا گیا؛ خاندانی رجحان قطعی طور پر ٹوٹ گیا", "6a137c97"], "d": ["1032 میں اورسیولو خاندان وینس سے مکمل طور پر نکال دیا گیا اور ڈوج دومینیکو فلابانیکو کو تخت پر بلایا گیا؛ ڈوجی کے خاندانی ہو جانے کے خلاف پہلا ادارہ جاتی قدم یہی ہے۔", "95963f43"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1035-11-12:0":{"b": ["کنود دی گریٹ فوت ہوا؛ بحرِ شمالی کی سلطنت بکھر گئی", "3df57da6"], "d": ["ڈنمارک، انگلستان اور ناروے کو ایک تخت پر متحد کرنے والا کنود (کنیوٹ) 12 نومبر 1035 کو فوت ہوا؛ 1018 سے ڈنمارک کا اور 1016 سے انگلستان کا بادشاہ تھا۔ ناروے 1028-1035 کے درمیان اس کا تھا؛ اتحاد اس کی وفات کے بعد زیادہ دیر نہ چلا۔", "cb4bc5bc"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1036-01-01:0":{"b": ["مستیسلاو کی وفات سے یاروسلاو واحد حکمران بنا؛ پیچنگوں کو بھاری شکست دی گئی", "34f5f3bb"], "d": ["1036 میں مستیسلاو کی وفات کے بعد یاروسلاو نے اس کے علاقے بھی (پولوتسک کے سوا) ضم کر کے کیفی روس کا واحد حکمران بن گیا؛ اسی دوران کیف پر حملہ آور پیچنگوں کو بھاری شکست دی (1037) اور آیا صوفیہ کیتھیڈرل کی تعمیر شروع کی۔", "cd963cdb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1038-01-01:0":{"b": ["بادشاہ اشتوان اول فوت ہوا؛ اربادی خاندان میں انتشار کا دور", "dd9fbb59"], "d": ["اشتوان کی 1038 کی وفات کے بعد 1077 تک جاری رہنے والے چالیس انتشار زدہ سال شروع ہوئے؛ ہنگری شہنشاہی-پاپائی کشمکش میں کھینچ لیا گیا۔ اربادی خاندان میں 1301 تک تئیس بادشاہ بدلے۔", "3e901e53"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1038-01-01:1":{"b": ["زیری افواج نے کلبی امیر احمد کو قتل کر دیا؛ اس کی جگہ بھائی حسن الصمصام آیا", "a8237799"], "d": ["لوگوں کی مدد مانگنے پر آنے والی زیری افواج احمد کو قتل کر دیتی ہیں؛ اس کی جگہ بھائی حسن الصمصام کو لایا جاتا ہے (TDV کی ابن الحواس مدخل 1040 دیتی ہے)۔", "d17c0e2e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1042-01-01:0":{"b": ["نارمنوں نے ملفی کو دارالحکومت چنا؛ لوہے کے بازو والا گوئیلمو آپولیا کا کاؤنٹ منتخب ہوا", "c99feeb9"], "d": ["جنوبی اٹلی میں بازنطین کے خلاف لڑنے والے نارمن کرائے کے سپاہیوں نے 1042 میں ملفی کو اپنا دارالحکومت چنا؛ اسی سال ستمبر میں تانکریڈ دے ہوتویل کا بیٹا گوئیلمو (لوہے کا بازو) کاؤنٹ منتخب ہوا۔ نارمن کاؤنٹی آپولیا کی عملی پیدائش یہی ہے۔", "89954197"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1043-01-01:0":{"b": ["یاروسلاو کی استنبول کی مہم تباہی پر ختم ہوئی", "69fc1e8f"], "d": ["1043 میں بیٹے ولادیمیر اور سردار ویشاتا کی قیادت میں روسی فوج نے قسطنطنیہ پر حملہ کیا؛ مہم بھاری شکست پر ختم ہوئی۔", "93bcdced"]},
